IEnumerator RoamRoutine()
{
    while (currentState == ZombieState.Roaming)
    {
        Vector3 roamTarget = GetRandomRoamPosition();
        if (agent.isOnNavMesh)
        {
            agent.isStopped = false;
            agent.speed = roamSpeed;
            agent.SetDestination(roamTarget);
        }
        yield return new WaitForSeconds(roamInterval);
    }
}

IEnumerator WaveRoutine()
{
    currentWave++;
    int zombiesToSpawn = initialZombiesPerWave + (currentWave - 1) * 2;
    for (int i = 0; i < zombiesToSpawn; i++)
    {
        SpawnZombie();
        yield return new WaitForSeconds(spawnInterval);
    }
}

